ALTER TABLE "Raffles"
ADD COLUMN IF NOT EXISTS "AutoEndWhenFull" boolean NOT NULL DEFAULT false;

CREATE TABLE IF NOT EXISTS "CueSets" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Title" character varying(200) NOT NULL,
  "Brand" character varying(100) NOT NULL,
  "Description" character varying(5000) NOT NULL DEFAULT '',
  "Price" numeric(10,2) NOT NULL,
  "Condition" character varying(50) NOT NULL DEFAULT 'good',
  "Location" character varying(200) NOT NULL DEFAULT '',
  "IncludesPlayingCue" boolean NOT NULL DEFAULT false,
  "IncludesBreakCue" boolean NOT NULL DEFAULT false,
  "IncludesJumpCue" boolean NOT NULL DEFAULT false,
  "IncludesCase" boolean NOT NULL DEFAULT false,
  "PlayingCueWeight" numeric(5,2) NULL,
  "PlayingCueLength" numeric(5,2) NULL,
  "PlayingCueTipSize" numeric(5,2) NULL,
  "PlayingCueShaftMaterial" character varying(100) NULL,
  "PlayingCueButtMaterial" character varying(100) NULL,
  "BreakCueWeight" numeric(5,2) NULL,
  "BreakCueLength" numeric(5,2) NULL,
  "BreakCueTipSize" numeric(5,2) NULL,
  "BreakCueShaftMaterial" character varying(100) NULL,
  "BreakCueButtMaterial" character varying(100) NULL,
  "JumpCueWeight" numeric(5,2) NULL,
  "JumpCueLength" numeric(5,2) NULL,
  "JumpCueTipSize" numeric(5,2) NULL,
  "JumpCueShaftMaterial" character varying(100) NULL,
  "JumpCueButtMaterial" character varying(100) NULL,
  "CaseCapacity" character varying(20) NULL,
  "CaseOpening" character varying(50) NULL,
  "CaseType" character varying(50) NULL,
  "CaseColor" character varying(100) NULL,
  "CaseMaterial" character varying(100) NULL,
  "Features" character varying(1000) NULL,
  "UserId" integer NOT NULL,
  "IsSold" boolean NOT NULL DEFAULT false,
  "SoldDate" timestamp without time zone NULL,
  "ViewCount" integer NOT NULL DEFAULT 0,
  "AverageRating" numeric(3,2) NOT NULL DEFAULT 0,
  "RatingCount" integer NOT NULL DEFAULT 0,
  "CreatedAt" timestamp without time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
  "UpdatedAt" timestamp without time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
  "IsFlagged" boolean NOT NULL DEFAULT false,
  "FlagReason" character varying(500) NULL,
  "ModerationStatus" character varying(50) NOT NULL DEFAULT 'approved',
  "ModeratedByUserId" integer NULL,
  "ModeratedAt" timestamp without time zone NULL,
  "ModerationNotes" character varying(1000) NULL,
  "LastPromptedAt" timestamp without time zone NULL,
  "LastUserResponseAt" timestamp without time zone NULL,
  "IsHidden" boolean NOT NULL DEFAULT false,
  "HiddenAt" timestamp without time zone NULL,
  CONSTRAINT "FK_CueSets_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users"("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "CueSetImages" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CueSetId" integer NOT NULL,
  "ImageUrl" character varying(500) NOT NULL,
  "DisplayOrder" integer NOT NULL,
  "IsPrimary" boolean NOT NULL,
  "UploadedAt" timestamp without time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
  CONSTRAINT "FK_CueSetImages_CueSets_CueSetId" FOREIGN KEY ("CueSetId") REFERENCES "CueSets"("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_CueSet_UserId" ON "CueSets" ("UserId");
CREATE INDEX IF NOT EXISTS "IX_CueSet_CreatedAt" ON "CueSets" ("CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_CueSet_IsSold" ON "CueSets" ("IsSold");
CREATE INDEX IF NOT EXISTS "IX_CueSetImage_CueSetId" ON "CueSetImages" ("CueSetId");
